  var old=c.methods.stream().filter(m->m.name.equals("negative")).findFirst().orElseThrow();var m=new MethodNode(ACC_STATIC,"nativeMaterialControlledNegativeBody",old.desc.replace(")Z","L"+F+";Z)Z"),null,old.exceptions.toArray(String[]::new));old.accept(m);int resolve=0,available=0,monitors=0,install=0,administration=0;MethodInsnNode consume=null;VarInsnNode previousStore=null,nextStore=null,focusParamLoad=null,adminParamLoad=null;
